// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [835496389, 481051077, 2891878853, 1182015941, 2648940997, 2318657989, 1003717061, 733772229, 3579154885, 1650983365, 2836648389, 504414661, 2632149445, 1000649157, 793461189, 136131013];
const blocks = ["NFC U+040000-U+040FFF", "NFC U+041000-U+041FFF", "NFC U+042000-U+042FFF", "NFC U+043000-U+043FFF", "NFC U+044000-U+044FFF", "NFC U+045000-U+045FFF", "NFC U+046000-U+046FFF", "NFC U+047000-U+047FFF", "NFC U+048000-U+048FFF", "NFC U+049000-U+049FFF", "NFC U+04A000-U+04AFFF", "NFC U+04B000-U+04BFFF", "NFC U+04C000-U+04CFFF", "NFC U+04D000-U+04DFFF", "NFC U+04E000-U+04EFFF", "NFC U+04F000-U+04FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 262144 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
